()) do\n            if typeof(folder) == \"Instance\" and typeof(folder) == \"Instance\" and folder:IsA(\"Folder\") and (folder.Name == \"Easy Ticket Quest\" or folder.Name == \"Hard Ticket Quest\") then\n                local current = nil\n                local target = nil\n                local typ = nil\n                local questName = folder.Name\n                for _, child in pairs(folder:GetChildren()) do\n                    if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") or child:IsA(\"IntValue\") then\n                        if child.Name == \"1\" then\n                            current = child.Value\n                        end\n                    end\n                end\n                local objective = folder:FindFirstChild(\"Objective\")\n                if objective then\n                    for _, child in pairs(objective:GetChildren()) do\n                        if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"StringValue\") and child.Name == \"1\" then\n                            local val = child.Value\n                            if val and val ~= \"\" then\n                                NexusState.ticketObjectiveText = tostring(val)\n                                local t, ty = parseQuestString(val)\n                                if t and ty then\n                                    target = t\n                                    typ = ty\n                                end\n                            end\n                        end\n                    end\n                end\n                if current and target and typ then\n                    return current, target, questName, typ\n                end\n            end\n        end\n        return nil\n    end\n\n    local function updateQuestStatus()\n        local current, target, questName, typ = getCurrentQuestProgress()\n        if current and target and questName then\n            NexusState.ticketTargetCount = target\n            NexusState.ticketCurrentCount = current\n            NexusState.ticketQuestActive = true\n            if current >= target then\n                if not NexusState.ticketQuestClaimed then\n                    NexusLib:Notify({ Title = \"Quest\", Message = \"Complete! Claiming reward...\", Duration = 2 })\n                    -- TP to NPC, turn in with retries, chain next quest right away.\n                    local turnedIn = false\n                    for _ = 1, 5 do\n                        if ticketGoFire(\"Quest\") then\n                            for _ = 1, 6 do\n                                task.wait(0.15)\n                                if not getCurrentQuestProgress() then\n                                    turnedIn = true\n                                    break\n                                end\n                            end\n                        end\n                        if turnedIn then break end\n                        task.wait(0.2)\n                    end\n                    if turnedIn then\n                        NexusState.ticketQuestClaimed = true\n                        NexusState.ticketLastFire = 0\n                        NexusState.ticketFailCount = 0\n                        NexusState.isDoingUseBaitQuest = false\n                        disableAllFishing()\n                        NexusState.ticketQuestActive = false\n                        NexusLib:Notify({ Title = \"Quest\", Message = \"Turned in. Claim toggle takes next quest.\", Duration = 3 })\n                    else\n                        NexusLib:Notify({ Title = \"Quest\", Message = \"Turn-in failed, retrying...\", Duration = 2 })\n                    end\n                end\n                NexusState.isDoingUseBaitQuest = false\n                Fishing.Flags.AutoSkill = false\n                Fishing.Flags.AutoSkillCheck = false\n                NexusState.ticketQuestActive = false\n                re