     else\n                exchangeAmount = 1\n            end\n        end\n    })\n\n    Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose an item\", {\n        Name = \"Choose an item\",\n        Options = {\"Trait Reroll\", \"EssenceOrb\"},\n        Default = \"Trait Reroll\",\n        Callback = function(value) exchangeType = value end\n    })), \"Dropdown\", \"Choose an item\", {\n        Name = \"Choose an item\",\n        Options = {\"Trait Reroll\", \"EssenceOrb\"},\n        Default = \"Trait Reroll\",\n        Callback = function(value) exchangeType = value end\n    })\n\n    local exchangeMethodDropdown = Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Exchange Method\", {\n        Name = \"Exchange Method\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = NexusState.exchange.method or \"Instant\",\n        Callback = function(value) NexusState.exchange.method = value end\n    })), \"Dropdown\", \"Exchange Method\", {\n        Name = \"Exchange Method\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = NexusState.exchange.method or \"Instant\",\n        Callback = function(value) NexusState.exchange.method = value end\n    })\n\n    ExchangeSection:CreateButton({\n        Name = \"Exchange now\",\n        Callback = function()\n            local userId = LocalPlayer.UserId\n            local userData = Data:FindFirstChild(tostring(userId))\n            if not userData then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Player data not found!\", Duration = 2 })\n                return\n            end\n            local crystal = userData:FindFirstChild(\"Crystal\")\n            local cash = userData:FindFirstChild(\"Cash\")\n            if not crystal or not cash then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Crystal or Cash not found!\", Duration = 2 })\n                return\n            end\n            local qty = exchangeAmount\n            local crystalNeed = qty * 5\n            local cashNeed = qty * 5000000\n            if crystal.Value < crystalNeed then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Not enough Crystals! Need \" .. crystalNeed .. \", have \" .. crystal.Value, Duration = 3 })\n                return\n            end\n            if cash.Value < cashNeed then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Not enough Cash! Need \" .. cashNeed .. \", have \" .. cash.Value, Duration = 3 })\n                return\n            end\n\n            NexusState.exchange.teleported = false\n            NexusState.exchange.oldPosition = nil\n            if NexusState.exchange.method == \"Teleport\" then\n                local npc = Workspace:FindFirstChild(\"NPC\")\n                if npc then\n                    local func = npc:FindFirstChild(\"Function\")\n                    if func then\n                        local nanjiang = func:FindFirstChild(\"Nanjiang\")\n                        if typeof(nanjiang) == \"Instance\" and nanjiang:IsA(\"Model\") then\n                            local hrp = nanjiang:FindFirstChild(\"HumanoidRootPart\")\n                            if hrp then\n                                local char = LocalPlayer.Character\n                                if char then\n                                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                    if root then\n                                        NexusState.exchange.oldPosition = root.Position\n                                        root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                        NexusState.exchange.teleported = true\n                                        task.wait(0.3)\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                if not NexusState.exchange.teleported then\n                    NexusLib:Notify({ Title = \"Exchange\", Message = \"Could not find Nanjiang, teleport failed. Continuing anyway.\", Duration = 3 })\n                end\n            end\n\n            local success, err = pcall(function()\n                Events.Exchange:FireServer(exchangeType, qty)\n            end)\n\n            if NexusState.exchange.teleported and NexusState.exchange.oldPosition then\n                task.wait(0.2)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.exchange.oldPosition)\n                        NexusState.exchange.oldPosition = nil\n                        NexusState.exchange.teleported = false\n                    end\n                end\n            end\n\n            if success then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Exchanged \" .. qty .. \" \" .. exchangeType .. \"!\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Exchange failed: \" .. tostring(err), Duration = 2 })\n            end\n        end\n    })\nend\n\n-- ============================================================\n-- ===== QUESTS TAB =====\n-- ============================================================\ndo\n    local QuestsTab = Window:CreateTab(\"Quests\")\n\n    -- Teleport to Ticket Quest Giver, open dialogue, fire action, go back.\n    -- StartDialogue first: server ignores ChooseDialogueOption with no open dialogue.\n    NexusState.ticketLastFire = NexusState.ticketLastFire or 0\n    NexusState.ticketFailCount = NexusState.ticketFailCount or 0\n    local function ticketGoFire(action)\n        if _G and _G.Events then\n            local sd = _G.Events:FindFirstChild(\"StartDialogue\")\n            local cd = _G.Events:FindFirstChild(\"ChooseDialogueOption\")\n            if not sd or not cd then return false end\n        end\n        local giver = nil\n        pcall(function()\n            local npc = Workspace:FindFirstChild(\"NPC\")\n            local npcFunc = npc and npc:FindFirstChild(\"Function\")\n            giver = npcFunc and npcFunc:FindFirstChild(\"Ticket Quest Giver\")\n        end)\n        if not giver then return false end\n        local extraData = { giver }\n        local charNow = LocalPlayer.Character\n        local root = charNow and charNow:FindFirstChild(\"HumanoidRootPart\")\n        local giverPos = nil\n        pcall(function()\n            if typeof(giver) == \"Instance\" and typeof(giver) == \"Instance\" and giver:IsA(\"Model\") then\n                local hrp = giver:FindFirstChild(\"HumanoidRootPart\")\n                if hrp then\n                    giverPos = hrp.Position\n                elseif giver.PrimaryPart then\n                    giverPos = giver.PrimaryPart.Position\n                else\n                    giverPos = giver:GetPivot().Position\n                end\n            elseif typeof(giver) == \"Instance\" and typeof(giver) == \"Instance\" and giver:IsA(\"BasePart\") then\n                giverPos = giver.Position\n            end\n        end)\n        local origCF = root and root.CFrame\n        if root and giverPos then\n            pcall(function() root.CFrame = CFrame.new(giverPos + Vector3.new(0, 3, 0)) end)\n            task.wait(0.45)\n        end\n        pcall(function()\n            Events.StartDialogue:FireServer(\"Ticket Quest Giver\", giver)\n        end)\n        task.wait(0.25)\n        pcall(function()\n            Events.ChooseDialogueOption:FireServer(\"Ticket Quest Giver\", 1, action, extraData)\n        end)\n        task.wait(0.2)\n        if origCF and root and root.Parent then\n            pcall(function() root.CFrame = origCF end)\n        end\n        return true\n    end\n\n    -- ===== AUTO CLAIM TICKET QUEST =====\n    do\n        local ClaimSection = QuestsTab:CreateSection(\"Auto Claim Ticket Quest\")\n        local questTypes = {\"Easy Quest\", \"Hard Quest\"}\n        local selectedQuest = questTypes[1]\n\n        local function HasActiveQuest()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false end\n            local quest = userData:FindFirstChild(\"Quest\")\n            if not quest then return false end\n            local main = quest:FindFirstChild(\"Main\")\n            if not main then return false end\n            for _, child in pairs(main:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Folder\") then\n                    local name = child.Name\n                    if name == \"Easy Ticket Quest\" or name == \"Hard Ticket Quest\" then\n                        return true\n                    end\n                end\n            end\n            return false\n        end\n\n        local claimDropdown = Cfg.register(ClaimSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Select Quest Type\", {\n            Name = \"Select Quest Type\",\n            Options = questTypes,\n            Default = selectedQuest,\n            Callback = function(value) selectedQuest = value end\n        })), \"Dropdown\", \"Select Quest Type\", {\n            Name = \"Select Quest Type\",\n            Options = questTypes,\n            Default = selectedQuest,\n            Callback = function(value) selectedQuest = value end\n        })\n\n        local autoClaimToggle = Cfg.register(ClaimSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Claim Ticket Quest (Fast)\", {\n            Name = \"Auto Claim Ticket Quest (Fast)\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoClaimRunning = value\n                if value then\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.autoClaimThread = task.spawn(function()\n                        while NexusState.autoClaimRunning do\n                            pcall(function()\n                                if not HasActiveQuest() then\n                                    if tick() - (NexusState.ticketLastFire    Placeholder = \"4\",\n            Default = tostring(NexusState.maxServerPlayers or 4),\n            Callback = function(text)\n                local n = tonumber(text)\n                if n and n >= 1 and n <= 50 then\n                    NexusState.maxServerPlayers = math.floor(n)\n                else\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Enter a number 1-50.\", Duration = 3 })\n                end\n            end\n        })\n\n        Cfg.register(HopSection:CreateButton(Cfg.wrap(\"Button\", \"Hop to Low Player Server\", {\n            Name = \"Join\",\n            Callback = function()\n                if tick() - (NexusState.hopCooldownAt or 0) < 30 then\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Hop cooldown, try again shortly.\", Duration = 3 })\n                    return\n                end\n                NexusLib:Notify({ Title = \"Server Hop\", Message = \"Searching low player server...\", Duration = 3 })\n                task.spawn(function()\n                    local maxP = NexusState.maxServerPlayers or 4\n                    local jobId, playing = findLowServer(maxP)\n                    if jobId then\n                        NexusState.hopCooldownAt = tick()\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = string.format(\"Joining server (%d/%d)...\", playing, maxP), Duration = 3 })\n                        pcall(function()\n                            Services.TeleportService:TeleportToPlaceInstance(game.PlaceId, jobId, LocalPlayer)\n                        end)\n                    else\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = \"No low player server found, try again.\", Duration = 3 })\n                    end\n                end)\n            end\n        })), \"Button\", \"Hop to Low Player Server\", nil)\n\n    -- ===== STREAMER MODE (FAKE NAME) & LANGUAGE & NEXUS SHIELD =====\n    do\n        local StreamerSection = SettingsTab:CreateSection(\"Streamer Mode (Fake Name)\")\n        Cfg.register(StreamerSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Fake Name Display\", {\n            Name = \"Fake Name Display\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    NexusState.enableFakeName()\n                else\n                    NexusState.disableFakeName()\n                end\n            end\n        })), \"Toggle\", \"Fake Name Display\", {\n            Name = \"Fake Name Display\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    NexusState.enableFakeName()\n                else\n                    NexusState.disableFakeName()\n                end\n            end\n        })\n\n        Cfg.register(StreamerSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Fake Username\", {\n            Name = \"Fake Username\",\n            Placeholder = \"NexusPlayer\",\n            Default = NexusState.fakeName or \"NexusPlayer\",\n            Callback = function(value)\n                if value and #value > 0 then\n                    NexusState.fakeName = value\n                end\n            end\n        })), \"Textbox\", \"Fake Username\", {\n            Name = \"Fake Username\",\n            Placeholder = \"NexusPlayer\",\n            Default = NexusState.fakeName or \"NexusPlayer\",\n            Callback = function(value)\n                if value and #value > 0 then\n                    NexusState.fakeName = value\n                end\n            end\n        })\n\n        Cfg.register(StreamerSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Fake Display Name\", {\n            Name = \"Fake Display Name\",\n            Placeholder = \"NexusPlayer\",\n            Default = NexusState.fakeDisplayName or \"NexusPlayer\",\n            Callback = function(value)\n                if value and #value > 0 then\n                    NexusState.fakeDisplayName = value\n                end\n            end\n        })), \"Textbox\", \"Fake Display Name\", {\n            Name = \"Fake Display Name\",\n            Placeholder = \"NexusPlayer\",\n            Default = NexusState.fakeDisplayName or \"NexusPlayer\",\n            Callback = function(value)\n                if value and #value > 0 then\n                    NexusState.fakeDisplayName = value\n                end\n            end\n        })\n\n        -- Doi ten ma khong che ID thi van bi report -> them o nhap UserId gia.\n        -- PlaceId va JobId duoc che tu dong (khong can nhap).\n        Cfg.register(StreamerSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Fake User ID\", {\n            Name = \"Fake User ID\",\n            Placeholder = \"0\",\n            Default = NexusState.fakeUserId or \"0\",\n            Callback = function(value)\n                if value and #tostring(value) > 0 then\n                    NexusState.fakeUserId = tostring(value)\n                end\n            end\n        })), \"Textbox\", \"Fake User ID\", {\n            Name = \"Fake User ID\",\n            Placeholder = \"0\",\n            Default = NexusState.fakeUserId or \"0\",\n            Callback = function(value)\n                if value and #tostring(value) > 0 then\n                    NexusState.fakeUserId = tostring(value)\n                end\n            end\n        })\n\n        -- Guild display: nhap ten guild that -> se doi sang fake guild de khong bi ban\n                Cfg.register(StreamerSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Fake ID Mode\", {\n            Name = \"Fake ID Mode\",\n            Options = {\"1 - Fake Number\", \"2 - Hide ID\"},\n            Default = \"1 - Fake Number\",\n            Callback = function(value)\n                if value and string.find(tostring(value), \"^2\") then\n                    NexusState.fakeIdMode = 2\n                else\n                    NexusState.fakeIdMode = 1\n                end\n            end\n        })), \"Dropdown\", \"Fake ID Mode\", {\n            Name = \"Fake ID Mode\",\n            Options = {\"1 - Fake Number\", \"2 - Hide ID\"},\n            Default = \"1 - Fake Number\",\n            Callback = function(value)\n                if value and string.find(tostring(value), \"^2\") then\n                    NexusState.fakeIdMode = 2\n                else\n                    NexusState.fakeIdMode = 1\n                end\n            end\n        })\nCfg.register(StreamerSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Real Guild Name (Optional)\", {\n            Name = \"Real Guild Name (Optional)\",\n            Placeholder = \"Current guild name\",\n            Default = NexusState.realGuildName or \"\",\n            Callback = function(value)\n                if value then\n                    NexusState.realGuildName = tostring(value):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n                    if #(NexusState.realGuildName or \"\") > 0 then\n                        NexusState.enableFakeName()\n                    end\n                end\n            end\n        })), \"Textbox\", \"Real Guild Name (Optional)\", {\n            Name = \"Real Guild Name (Optional)\",\n            Placeholder = \"Current guild name\",\n            Default = NexusState.realGuildName or \"\",\n            Callback = function(value)\n                if value then\n                    NexusState.realGuildName = tostring(value):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n                    if #(NexusState.realGuildName or \"\") > 0 then\n                        NexusState.enableFakeName()\n                    end\n                end\n            end\n        })\n\n\n        local LangSection = SettingsTab:CreateSection(\"Language & Localization\")\n        local langOptions = {\"Auto (Roblox Locale)\", \"English\", \"Espanol\", \"Portugues\", \"Thai\", \"Bahasa Indonesia\"}\n        local langMap = {\n            [\"Auto (Roblox Locale)\"] = \"auto\",\n            [\"English\"] = \"en\",\n            [\"Espanol\"] = \"es\",\n            [\"Portugues\"] = \"pt\",\n            [\"Thai\"] = \"th\",\n            [\"Bahasa Indonesia\"] = \"id\"\n        }\n        Cfg.register(LangSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"UI Language\", {\n            Name = \"UI Language\",\n            Options = langOptions,\n            Default = \"Auto (Roblox Locale)\",\n            Callback = function(value)\n                NexusState.currentLanguage = langMap[value] or \"auto\"\n                pcall(function()\n                    if I18n and I18n.applyLanguage then\n                        I18n.applyLanguage()\n                    end\n                end)\n                NexusLib:Notify({\n                    Title = \"Language\",\n                    Message = \"Language set to: \" .. tostring(value),\n                    Duration = 2\n                })\n            end\n        })), \"Dropdown\", \"UI Language\", {\n            Name = \"UI Language\",\n            Options = langOptions,\n            Default = \"Auto (Roblox Locale)\",\n            Callback = function(value)\n                NexusState.currentLanguage = langMap[value] or \"auto\"\n                pcall(function()\n                    if I18n and I18n.applyLanguage then\n                        I18n.applyLanguage()\n                    end\n                end)\n                NexusLib:Notify({\n                    Title = \"Language\",\n                    Message = \"Language set to: \" .. tostring(value),\n                    Duration = 2\n                })\n            end\n        })\n\n        local ShieldSection = SettingsTab:CreateSection(\"Nexus Shield\")\n        -- AN TOAN: Nexus Shield bat vinh vien, user KHONG TAT DUOC.\n        NexusState.antiReportEnabled = true\n        Cfg.register(ShieldSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Anti-Report Nexus Users\", {\n            Name = \"Anti-Report Nexus Users\",\n            Default = true,\n            Callback = function(value)\n                -- Bao ve: bat an toan -> neu user thu tat thi bao + luon bat lai\n                NexusState.antiReportEnabled = true\n                NexusLib:Notify({\n                    Title = \"Nexus Shield\",\n                    Message = \"An toan: Nexus Shield luon bat, khong the tat!\",\n                    Duration = 3\n                })\n            end\n        })), \"Toggle\", \"Anti-Report Nexus Users\", {\n            Name = \"Anti-Report Nexus Users\",\n            Default = true,\n            Callback = function(value)\n                -- Bao ve: bat an toan -> neu user thu tat thi bao + luon bat lai\n                NexusState.antiReportEnabled = true\n                NexusLib:Notify({\n                    Title = \"Nexus Shield\",\n                    Message = \"An toan: Nexus Shield luon bat, khong the tat!\",\n                    Duration = 3\n                })\n            end\n        })\n    end\n\n    -- ===== ESP SECTION =====\n    do\n        local EspSection = SettingsTab:CreateSection(\"ESP\")\n        \n        -- ===== ESP PLAYERS =====\n        local espEnabled = false\n        local espThread = nil\n        local espConnections = {}\n        local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n        \n        local function getPlayerStats(player)\n            local stats = {\n                Level = \"N/A\",\n                Cash = \"N/A\",\n                Rod = \"N/A\",\n       