 = \"Actualiser la liste\",\n            [\"Delete Job ID\"] = \"Supprimer le Job ID\",\n            [\"Join by Job ID\"] = \"Rejoindre par Job ID\",\n            [\"Check Current Players\"] = \"Voir les joueurs actuels\",\n            [\"Teleport to Player\"] = \"TP au joueur\",\n            [\"Spectate Player\"] = \"Specter un joueur\",\n            [\"Teleport To Current Weather\"] = \"TP  l'le de la mto actuelle\",\n            [\"Teleport to Recommend Island\"] = \"TP  l'le recommande\",\n            [\"Teleport to selected NPC\"] = \"TP au PNJ choisi\",\n            [\"Teleport to selected Secret Rod\"] = \"TP  la canne secrte choisie\",\n            [\"TP to Maoshan\"] = \"TP  Maoshan\",\n            [\"TP to Spirit\"] = \"TP  l'esprit\",\n            [\"TP to Taoist\"] = \"TP au taoste\",\n            [\"UI Language\"] = \"Langue de l'interface\",\n            [\"Skill Mode\"] = \"Mode comptence\",\n            [\"Skill Sequence Order\"] = \"Ordre des comptences\",\n            [\"Skill Delay (seconds)\"] = \"Dlai comptence (secondes)\",\n            [\"Select Island\"] = \"Choisir une le\",\n            [\"Island Selection Mode\"] = \"Mode de slection d'le\",\n            [\"Select Bait to Buy\"] = \"Choisir l'appt  acheter\",\n            [\"Select Rod to Buy\"] = \"Choisir la canne  acheter\",\n            [\"Select Rod to Craft\"] = \"Choisir la canne  fabriquer\",\n            [\"Buy Method\"] = \"Mthode d'achat\",\n            [\"Craft Method\"] = \"Mthode de fabrication\",\n            [\"Upgrade Method\"] = \"Mthode d'amlioration\",\n            [\"Learn Method\"] = \"Mthode d'apprentissage\",\n            [\"Exchange Method\"] = \"Mthode d'change\",\n            [\"Reroll Method\"] = \"Mthode de reroll\",\n            [\"Method Claim\"] = \"Mthode de rclamation\",\n            [\"Method Sell #1\"] = \"Mthode de vente n1\",\n            [\"Method Sell #2\"] = \"Mthode de vente n2\",\n            [\"Auto Enzo Fight Mode\"] = \"Mode combat Enzo auto\",\n            [\"Nameless Mode\"] = \"Mode sans nom\",\n            [\"Filter #1\"] = \"Filtre n1\",\n            [\"Select Banner\"] = \"Choisir un banner\",\n            [\"Select Player\"] = \"Choisir un joueur\",\n            [\"Select Quest Type\"] = \"Choisir le type de qute\",\n            [\"Select Skill\"] = \"Choisir une comptence\",\n            [\"Target Trait\"] = \"Trait cible\",\n            [\"Choose a Bait\"] = \"Choisir un appt\",\n            [\"Choose an island\"] = \"Choisir une le\",\n            [\"Choose an item\"] = \"Choisir un objet\",\n            [\"Buy Amount\"] = \"Quantit d'achat\",\n            [\"Buy When Below\"] = \"Acheter quand en dessous\",\n            [\"Number of baits to craft\"] = \"Nombre d'appts  fabriquer\",\n            [\"Quantity\"] = \"Quantit\",\n            [\"Tickets per roll\"] = \"Tickets par tirage\",\n            [\"Fly Speed\"] = \"Vitesse de vol\",\n            [\"Walk Speed\"] = \"Vitesse de marche\",\n            [\"Risk hits/sec (1-200)\"] = \"Clics/seconde (1-200)\",\n, Placeholder = \"50\", Default = \"50\", Callback = function(V)\n        NexusState.flySpeed = tonumber(V) or 50\n    end })\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Noclip\", { Name = \"Noclip\", Default = false, Callback = function(V) MiscFlags.Noclip = V end })), \"Toggle\", \"Noclip\", { Name = \"Noclip\", Default = false, Callback = function(V) MiscFlags.Noclip = V end })\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Infinite Jump\", { Name = \"Infinite Jump\", Default = false, Callback = function(V) MiscFlags.InfiniteJump = V end })), \"Toggle\", \"Infinite Jump\", { Name = \"Infinite Jump\", Default = false, Callback = function(V) MiscFlags.InfiniteJump = V end })\n\n    local function findWaterParts()\n        local parts = {}\n        for _, v in pairs(Workspace:GetDescendants()) do\n            if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"BasePart\") then\n                local name = v.Name:lower()\n                if name:match(\"water\") or name:match(\"ocean\") or v.Material == Enum.Material.Water then\n                    table.insert(parts, v)\n                end\n            end\n        end\n        return parts\n    end\n\n    local function enableWaterWalk()\n        if NexusState.waterWalkEnabled then return end\n        NexusState.waterWalkEnabled = true\n        NexusState.waterPartsList = findWaterParts()\n        for _, part in ipairs(NexusState.waterPartsList) do part.CanCollide = true end\n        NexusState.waterPart = Instance.new(\"Part\")\n        NexusState.waterPart.Size = Vector3.new(16, 1, 16)\n        NexusState.waterPart.Transparency = 1\n        NexusState.waterPart.Anchored = true\n        NexusState.waterPart.CanCollide = true\n        NexusState.waterPart.Name = \"WaterWalkPart\"\n        NexusState.waterPart.Parent = Workspace\n        local char = LocalPlayer.Character\n        if char and char:FindFirstChild(\"HumanoidRootPart\") then\n            NexusState.waterY = char.HumanoidRootPart.Position.Y - 3.2\n        else\n            NexusState.waterY = 0\n        end\n        if NexusState.waterWalkConnection then NexusState.waterWalkConnection:Disconnect() end\n        NexusState.waterWalkConnection = RunService.RenderStepped:Connect(function()\n            if not NexusState.waterWalkEnabled then return end\n            local char = LocalPlayer.Character\n            if not char then return end\n            local root = char:FindFirstChild(\"HumanoidRootPart\")\n            if not root then return end\n            if NexusState.waterPart then\n                NexusState.waterPart.Position = Vector3.new(root.Position.X, NexusState.waterY, root.Position.Z)\n            end\n        end)\n    end\n\n    local function disableWaterWalk()\n        if not NexusState.waterWalkEnabled then return end\n        NexusState.waterWalkEnabled = false\n        if NexusState.waterWalkConnection then\n            NexusState.waterWalkConnection:Disconnect()\n            NexusState.waterWalkConnection = nil\n        end\n        if NexusState.waterPart then\n            NexusState.waterPart:Destroy()\n            NexusState.waterPart = nil\n        end\n        for _, part in ipairs(NexusState.waterPartsList) do\n            if part and part.Parent then\n                part.CanCollide = false\n            end\n        end\n        NexusState.waterPartsList = {}\n    end\n\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Walk On Water\", {\n        Name = \"Walk On Water\",\n        Default = false,\n        Callback = function(V)\n            MiscFlags.WalkOnWater = V\n            if V then enableWaterWalk() else disableWaterWalk() end\n        end\n    })), \"Toggle\", \"Walk On Water\", {\n        Name = \"Walk On Water\",\n        Default = false,\n        Callback = function(V)\n            MiscFlags.WalkOnWater = V\n            if V then enableWaterWalk() else disableWaterWalk() end\n        end\n    })\n\n    -- World & Misc\n    do\n        local WorldSection = SettingsTab:CreateSection(\"World & Misc\")\n        local origA, origB, origT, origBr, origOA = Lighting.Ambient, Lighting.ColorShift_Bottom, Lighting.ColorShift_Top, Lighting.Brightness, Lighting.OutdoorAmbient\n        Cfg.register(WorldSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Full Bright\", {\n            Name = \"Full Bright\",\n            Default = false,\n            Callback = function(V)\n                MiscFlags.FullBright = V\n                if not V then\n                    Lighting.Ambient = origA\n                    Lighting.ColorShift_Bottom = origB\n                    Lighting.ColorShift_Top = origT\n                    Lighting.Brightness = origBr\n                    Lighting.OutdoorAmbient = origOA\n                end\n            end\n        })), \"Toggle\", \"Full Bright\", {\n            Name = \"Full Bright\",\n            Default = false,\n            Callback = function(V)\n                MiscFlags.FullBright = V\n                if not V then\n                    Lighting.Ambient = origA\n                    Lighting.ColorShift_Bottom = origB\n                    Lighting.ColorShift_Top = origT\n                    Lighting.Brightness = origBr\n                    Lighting.OutdoorAmbient = origOA\n                end\n            end\n        })\n\n        WorldSection:CreateButton({\n            Name = \"Redeem All Codes\",\n            Callback = function()\n                task.spawn(function()\n                    for _, code in ipairs(CODES) do\n                        pcall(function() Events.RedeemCode:FireServer(code) end)\n                        task.wait(0.3)\n                    end\n                    NexusLib:Notify({ Title = \"Codes\", Message = \"All codes redeemed!\", Duration = 3 })\n                end)\n            end\n        })\n\n        WorldSection:CreateButton({\n            Name = \"Performance Mod\",\n            Callback = function()\n                pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)\n                local t = Workspace:FindFirstChildOfClass(\"Terrain\")\n                if t then\n                    t.WaterWaveSize = 0\n                    t.WaterWaveSpeed = 0\n                    t.WaterReflectance = 0\n                    t.WaterTransparency = 1\n                end\n                Lighting.GlobalShadows = false\n                Lighting.FogEnd = 9e9\n                Lighting.ShadowSoftness = 0\n                Lighting.EnvironmentDiffuseScale = 0\n                Lighting.EnvironmentSpecularScale = 0\n                for _, v in pairs(Lighting:GetChildren()) do\n                    if typeof(v) == \"Instance\" and (v:IsA(\"BlurEffect\") or v:IsA(\"SunRaysEffect\") or v:IsA(\"ColorCorrectionEffect\") or v:IsA(\"BloomEffect\") or v:IsA(\"DepthOfFieldEffect\")) then\n                        v:Destroy()\n                    end\n                end\n                for _, v in pairs(Workspace:GetDescendants()) do\n                    if typeof(v) == \"Instance\" then\n                        if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"BasePart\") then\n                            v.Material = Enum.Material.SmoothPlastic\n                            v.Reflectance = 0\n                            v.CastShadow = false\n                        elseif typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Decal\") or v:IsA(\"Texture\") or v:IsA(\"ParticleEmitter\") or v:IsA(\"Trail\") or v:IsA(\"Fire\") or v:IsA(\"Smoke\") or v:IsA(\"Sparkles\") then\n                            v:Destroy()\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = \"Performance\", Message = \"Optimized Game!\", Duration = 3 })\n            end\n        })\n        Cfg.register(WorldSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Enable Notifications\", {\n            Name = \"Enable Notifications\",\n            Default = true,\n            Callback = function(value)\n                NexusState.notificationsEnabled = value\n                NexusLib:Notify({\n                    Title = \"Notifications\",\n                    Message = value and \"Enabled\" or \"Disabled\",\n                    Duration = 2\n                })\n            end\n        })), \"Toggle\", \"Enable Notifications\", {\n            Name = \"Enable Notifications\",\n            Default = true,\n            Callback = function(value)\n                NexusState.notificationsEnabled = value\n                NexusLib:Notify({\n                    Title = \"Notifications\",\n                    Message = value and \"Enabled\" or \"Disabled\",\n                    Duration = 2\n                })\n            end\n        })\n    end\n\n\n        local HopSection = SettingsTab:CreateSection(\"Server Hop\")\n        NexusState.maxServerPlayers = NexusState.maxServerPlayers or 4\n        NexusState.hopCooldownAt = NexusState.hopCooldownAt or 0\n\n        local function fetchServers(cursor)\n            local reqFn = (syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)\n            if type(reqFn) ~= \"function\" then return nil end\n            local url = string.format(\"https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100\", game.PlaceId)\n            if cursor and cursor ~= \"\" then url = url .. \"&cursor=\" .. cursor end\n            local ok, res = pcall(reqFn, { Url = url, Method = \"GET\" })\n            if not ok or not res then return nil end\n            local body = res.Body or res.body\n            if type(body) ~= \"string\" or body == \"\" then return nil end\n            local ok2, data = pcall(function() return Services.HttpService:JSONDecode(body) end)\n            if not ok2 or type(data) ~= \"table\" then return nil end\n            return data\n        end\n\n        local function findLowServer(maxPlayers)\n            local cursor = \"\"\n            for _ = 1, 5 do\n                local data = fetchServers(cursor)\n                if not data or not data.data then return nil end\n                for _, srv in ipairs(data.data) do\n                    local playing = tonumber(srv.playing) or 999\n                    local maxP = tonumber(srv.maxPlayers) or 0\n                    if srv.id and srv.id ~= game.JobId and playing < maxP and playing <= maxPlayers then\n                        return srv.id, playing, maxP\n                    end\n                end\n                cursor = data.nextPageCursor\n                if not cursor or cursor == \"\" then break end\n            end\n            return nil\n        end\n\n\n        Cfg.register(HopSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Max Players\", {\n            Name = \"Max Players\",\n            Placeholder = \"4\",\n            Default = tostring(NexusState.maxServerPlayers or 4),\n            Callback = function(text)\n                local n = tonumber(text)\n                if n and n >= 1 and n <= 50 then\n                    NexusState.maxServerPlayers = math.floor(n)\n                else\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Enter a number 1-50.\", Duration = 3 })\n                end\n            end\n        })), \"Textbox\", \"Max Players\", {\n            Name = \"Max Players\",\n            Placeholder = \"4\",\n            Default = tostring(NexusState.maxServerPlayers or 4),\n            Callback = function(text)\n                local n = tonumber(text)\n                if n and n >= 1 and n <= 50 then\n                    NexusState.maxServerPlayers = math.floor(n)\n                else\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Enter a number 1-50.\", Duration = 3 })\n                end\n            end\n        })\n\n        Cfg.register(HopSection:CreateButton(Cfg.wrap(\"Button\", \"Hop to Low Player Server\", {\n            Name = \"Join\",\n            Callback = function()\n                if tick() - (NexusState.hopCooldownAt or 0) < 30 then\n                    NexusLib:Nothile task.wait(3) do\n            if MiscFlags.AutoEquipBait then\n                pcall(function()\n                    local userId = LocalPlayer.UserId\n                    local userData = Data:FindFirstChild(tostring(userId))\n                    if not userData then return end\n                    local equippedBaitValue = userData:FindFirstChild(\"EquippedBait\")\n                    if not equippedBaitValue then return end\n                    local currentBait = equippedBaitValue.Value or \"\"\n                    local best = GetBestBait()\n                    if best and best ~= currentBait then\n                        if EquipBait(best) then\n                            NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Equipped best bait: \" .. best, Duration = 2 })\n                        end\n                    end\n                end)\n            end\n        end\n    end)\n\n    -- ===== AUTO NAMELESS OCTOPARASITE =====\n    do\n        local NAMELESS_NAME = \"Nameless Octoparasite\"\n        local RHY_LANES = { \"A\", \"S\", \"D\" }\n        local RHY_KEYS = { A = Enum.KeyCode.A, S = Enum.KeyCode.S, D = Enum.KeyCode.D }\n        local RHY_WINDOW = 0.22\n        local RHY_SPEED = 1.15 / 1.4\n        local RHY_BAR_FALLBACK = 0.85\n\n        NexusState.Nameless = {\n            Enabled = false,\n            Mode = \"Safe\",\n            RiskRate = 25,\n            Band = 0.08,\n            Lag = 0.03,\n            Active = false,\n            SignalUntil = 0,\n            Config = nil,\n            Method = nil,\n            RiskThread = nil,\n            NextPress = {},\n            Stats = { hit = 0, spam = 0 },\n        }\n        local Rhy = NexusState.Nameless\n\n        local function rhyFindNameless()\n            local roots = {}\n            local ocean = Workspace:FindFirstChild(\"Ocean\")\n            if ocean then\n                local boss = ocean:FindFirstChild(\"Boss\")\n                if boss then\n                    local fn = boss:FindFirstChild(\"FishName\")\n                    if fn then table.insert(roots, fn) end\n                    table.insert(roots, boss)\n                end\n                table.insert(roots, ocean)\n            end\n            local fishes = Workspace:FindFirstChild(\"Fishes\")\n            if fishes then table.insert(roots, fishes) end\n            for _, root in ipairs(roots) do\n                local ok, found = pcall(function() return root:FindFirstChild(NAMELESS_NAME, true) end)\n                if ok and found then return found end\n            end\n            return nil\n        end\n\n        local function rhyPivotOf(inst)\n            if not inst then return nil end\n            local ok, cf = pcall(function()\n                if typeof(inst) == \"Instance\" and typeof(inst) == \"Instance\" and inst:IsA(\"BasePart\") then return inst.CFrame end\n                if typeof(inst) == \"Instance\" and typeof(inst) == \"Instance\" and inst:IsA(\"Model\") then\n                    if inst.PrimaryPart then return inst.PrimaryPart.CFrame end\n                    return inst:GetPivot()\n                end\n                local part = inst:FindFirstChildWhichIsA(\"BasePart\", true)\n                if part then return part.CFrame end\n                return nil\n            end)\n            if ok and cf then return cf end\n            return nil\n        end\n\n        local function rhyTeleportToNameless()\n            local model = rhyFindNameless()\n            if not model then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Cannot find \" .. NAMELESS_NAME .. \" in Workspace (boss not spawned yet?)\", Duration = 3 })\n                return false\n            end\n            local cf = rhyPivotOf(model)\n            if not cf then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Found boss but could not get its position!\", Duration = 3 })\n                return false\n            end\n            local char = LocalPlayer.Character\n            local hrp = char and (char:FindFirstChild(\"HumanoidRootPart\") or char.PrimaryPart)\n            if not hrp then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Character not found!\", Duration = 2 })\n                return false\n            end\n            hrp.CFrame = cf + Vector3.new(0, 12, 0)\n            NexusLib:Notify({ Title = \"Nameless\", Message = \"Teleported to \" .. NAMELESS_NAME, Duration = 2 })\n            return true\n        end\n\n        local function rhyPress(laneFrame, lane)\n            local methods = {\n                function()\n                    if not firesignal then return false end\n                    local btn = laneFrame and laneFrame:FindFirstChild(\"Button\")\n                    if not btn then return false end\n                    if not (typeof(btn) == \"Instance\" and (btn:IsA(\"TextButton\") or btn:IsA(\"ImageButton\"))) then return false end\n                    firesignal(btn.MouseButton1Click)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService(\"VirtualInputManager\")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, game)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, game)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService(\"VirtualInputManager\")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, nil)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, nil)\n                    return true\n                end,\n            }\n            if Rhy.Method then\n                local ok, res = pcall(methods[Rhy.Method])\n                if ok and res then return true end\n                Rhy.Method = nil\n            end\n            for i, fn in ipairs(methods) do\n                local ok, res = pcall(fn)\n                if ok and res then\n                    Rhy.Method = i\n                    return true\n                end\n            end\n            return false\n        end\n\n        local function rhyGui()\n            local fishing = MainGui and MainGui:FindFirstChild(\"Fishing\")\n            if not fishing then return nil, nil end\n            return fishing:FindFirstChild(\"Rhythm\"), fishing\n        end\n\n        local function rhyUiActive()\n            local gui, fishing = rhyGui()\n            if not gui or not fishing then return false end\n            return gui.Visible == true and fishing.Visible == true\n        end\n\n        local function rhyMaxBand()\n            local m = RHY_WINDOW - RHY_SPEED * (Rhy.Lag or 0) - 0.02\n            if m < 0.01 then m = 0.01 end\n            return m\n        end\n\n        local function rhyScan(now)\n            local gui = rhyGui()\n            if not gui then return end\n            for _, lane in ipairs(RHY_LANES) do\n                local laneFrame = gui:FindFirstChild(\"Progression\" .. lane)\n                if laneFrame then\n                    local barY = RHY_BAR_FALLBACK\n                    local barFrame = laneFrame:FindFirstChild(\"BarFrame\")\n                    if barFrame then\n                        local okB, y = pcall(function() return barFrame.Position.Y.Scale end)\n                        if okB and type(y) == \"number\" then barY = y end\n                    end\n                    local band = math.clamp(Rhy.Band, 0.01, rhyMaxBand())\n                    local inWindow = 0\n                    for _, note in ipairs(laneFrame:GetChildren()) do\n                        if note.Name == \"Note_FX\" then\n                            local okP, y = pcall(function() return note.Position.Y.Scale end)\n                            if okP and type(y) == \"number\" then\n                                if math.abs((y + RHY_SPEED * Rhy.Lag) - barY) <= band then\n                                    inWindow = inWindow + 1\n                                end\n                            end\n                        end\n                    end\n                    if inWindow > 5 then inWindow = 5 end\n                    for _ = 1, inWindow do\n                        if rhyPress(laneFrame, lane) then\n                            Rhy.Stats.hit = Rhy.Stats.hit + 1\n                        end\n                    end\n                end\n            end\n        end\n\n        local function rhyStartRisk()\n            if Rhy.RiskThread then return end\n            Rhy.RiskThread = task.spawn(function()\n                while alive() and Rhy.Enabled and Rhy.Mode == \"Risk\" and Rhy.Active do\n                    local rate = math.clamp(tonumber(Rhy.RiskRate) or 25, 1, 200)\n                    local burst = math.max(1, math.floor(rate / 20))\n                    for _ = 1, burst do\n                        pcall(function() Events.RhythmHit:FireServer(\"hit\") end)\n                        Rhy.Stats.spam = Rhy.Stats.spam + 1\n                    end\n                    task.wait(burst / rate)\n                end\n                Rhy.RiskThread = nil\n            end)\n        end\n\n        if runtimeEnv.NexusRhyStart then pcall(function() runtimeEnv.NexusRhyStart:Disconnect() end) end\n        if runtimeEnv.NexusRhyStop then pcall(function() runtimeEnv.NexusRhyStop:Disconnect() end) end\n        if runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) end\n        if runtimeEnv.NexusNamelessBGM then pcall(function() runtimeEnv.NexusNamelessBGM:Disconnect() end) end\n        if runtimeEnv.NexusNamelessP2 then pcall(function() runtimeEnv.NexusNamelessP2:Disconnect() end) end\n\n        pcall(function()\n            local evStart = Events:FindFirstChild(\"RhythmStart\")\n            if evStart then\n                runtimeEnv.NexusRhyStart = evStart.OnClientEvent:Connect(function(cfg)\n                    if not alive() then return end\n                    Rhy.Config = cfg\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    Rhy.Stats = { hit = 0, spam = 0 }\n                    Rhy.NextPress = {}\n                    if Rhy.Enabled then\n                        local hp = cfg and (cfg.FinalMaxHP or cfg.HPFinalPhase)\n                        NexusLib:Notify({\n                            Title = \"Auto Nameless\",\n                            Message = \"Nameless started [\" .. tostring(Rhy.Mode) .. \"]\" .. (hp and (\" | HP \" .. tostring(hp)) or \"\"),\n                            Duration = 3,\n                        })\n                        if Rhy.Mode == \"Risk\" then rhyStartRisk() end\n                    end\n                end)\n            end\n            local evStop = Events:FindFirstChild(\"RhythmStop\")\n            if evStop then\n                runtimeEnv.NexusRhyStop = evStop.OnClientEvent:Connect(function()\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                end)\n            end\n        end)\n\n        -- Nameless remotes captured after kill (remote.txt): BossPhaseBGM(name, sound) + BossPhase2Setup().\n        -- Arm the minigame on either remote so Auto Nameless works even when RhythmStart is late/missing.\n        pcall(function()\n            local evBGM = Events:FindFirstChild(\"BossPhaseBGM\")\n            if evBGM then\n                runtimeEnv.NexusNamelessBGM = evBGM.OnClientEvent:Connect(function(bossName, _sound)\n                    if not alive() then return end\n                    if bossName ~= nil and tostring(bossName) ~= \"Nameless Octoparasite\" then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Nameless boss signal [\" .. tostring(Rhy.Mode) .. \"]\", Duration = 3 })\n                    end\n                end)\n            end\n            local evP2 = Events:FindFirstChild(\"BossPhase2Sraft Rod\"] = \"Buat Pancingan\",\n            [\"Auto Buy Bait\"] = \"Auto Beli Umpan\",\n            [\"Auto Buy Rod\"] = \"Auto Beli Pancingan\",\n            [\"Learn Skills\"] = \"Pelajari Skill\",\n            [\"Trait Reroll\"] = \"Reroll Sifat\",\n            [\"Craft Bait\"] = \"Buat Umpan\",\n            [\"Auto Gacha\"] = \"Auto Gacha\",\n            [\"Exchange Items\"] = \"Tukar Barang\",\n            [\"Auto Claim Ticket Quest\"] = \"Auto Klaim Misi Tiket\",\n            [\"Daily Quests\"] = \"Misi Harian\",\n            [\"Material Farming\"] = \"Farm Bahan\",\n            [\"Auto Do Ticket Quest\"] = \"Auto Jalankan Misi Tiket\",\n            [\"Character Upgrade\"] = \"Tingkatkan Karakter\",\n            [\"Character\"] = \"Karakter\",\n            [\"World & Misc\"] = \"Dunia & Lainnya\",\n            [\"Streamer Mode (Fake Name)\"] = \"Mode Streamer (Nama Palsu)\",\n            [\"Language & Localization\"] = \"Bahasa & Lokalisasi\",\n            [\"Nexus Shield\"] = \"Perisai Nexus\",\n            [\"Staff Watch\"] = \"Deteksi Staff\",\n            [\"ESP\"] = \"ESP\",\n            [\"Lock catch bar\"] = \"Kunci bilah tangkapan\",\n            [\"Auto Cast\"] = \"Lempar Otomatis\",\n            [\"Auto Farm Boss\"] = \"Auto Farm Boss\",\n            [\"Auto Farm Secret Boss\"] = \"Auto Farm Secret Boss\",\n            [\"Auto Skill\"] = \"Auto Skill\",\n            [\"Auto Sell Fish\"] = \"Auto Jual Ikan\",\n            [\"Auto Enzo\"] = \"Auto Enzo QTE\",\n            [\"Anti AFK\"] = \"Anti AFK\",\n            [\"Farm On Weather\"] = \"Auto Farm Berdasarkan Cuaca\",\n            [\"Auto Equip Best Bait\"] = \"Pasang Umpan Terbaik\",\n            [\"Auto Equip Fishing Rod (Slot 1)\"] = \"Pegang Pancingan Otomatis\",\n            [\"Auto Nameless\"] = \"Auto Tanpa Nama\",\n            [\"Auto Favourite Fishes\"] = \"Auto Favoritkan Ikan\",\n            [\"Auto Teleport + Interact (Pray) Spirit\"] = \"Auto Doa Roh\",\n            [\"Enable Auto Farm Fish\"] = \"Aktifkan Auto Farm\",\n            [\"Auto Do Daily Quest\"] = \"Auto Misi Harian\",\n            [\"Auto Do Ticket Quest (Fast)\"] = \"Auto Misi Tiket (Cepat)\",\n            [\"Auto Claim Ticket Quest (Fast)\"] = \"Auto Klaim Tiket (Cepat)\",\n            [\"Auto Rebirth\"] = \"Auto Kelahiran Kembali\",\n            [\"Auto craft bait\"] = \"Auto buat umpan\",\n            [\"Auto craft selected rod\"] = \"Auto buat pancingan\",\n            [\"Auto fish for bait materials\"] = \"Auto pancing bahan umpan\",\n            [\"Fly Mode\"] = \"Mode Terbang\",\n            [\"Walk On Water\"] = \"Berjalan di Atas Air\",\n            [\"Infinite Jump\"] = \"Lompat Tak Terbatas\",\n            [\"Noclip\"] = \"Noclip\",\n            [\"Full Bright\"] = \"Kecerahan Penuh\",\n            [\"Fake Name Display\"] = \"Nama Palsu Aktif\",\n            [\"Anti-Report Nexus Users\"] = \"Anti-Laporkan Pengguna Nexus\",\n            [\"Enable Staff Watch\"] = \"Aktifkan Deteksi Staff\",\n            [\"Enable Notifications\"] = \"Aktifkan Notifikasi\",\n            [\"UI Language\"] = \"Bahasa UI\",\n            [\"Skill Mode\"] = \"Mode Skill\",\n            [\"Skill Sequence Order\"] = \"Urutan Skill\",\n            [\"Skill Delay (seconds)\"] = \"Jeda Skill (detik)\",\n            [\"Select Island\"] = \"Pilih Pulau\",\n            [\"Buy Now\"] = \"Beli Sekarang\",\n            [\"Craft rod now\"] = \"Buat Pancingan Sekarang\",\n            [\"Craft bait now\"] = \"Buat Umpan Sekarang\",\n            [\"Exchange now\"] = \"Tukar Sekarang\"\n        }\n    }\n\n    function I18n.getCurrentLanguage()\n        if NexusState.currentLanguage == \"auto\" then\n            return NexusState.detectedLanguage or \"en\"\n        end\n        return NexusState.currentLanguage or \"en\"\n    end\n\n    function I18n.get(key, fallback)\n        if not key or type(key) ~= \"string\" then return fallback or key end\n        local lang = I18n.getCurrentLanguage()\n        if lang == \"en\" then return fallback or key end\n        local dict = DICTIONARY[lang]\n        if dict and dict[key] then return dict[key] end\n        return fallback or key\n    end\n\n    local function translateObject(obj)\n        if not obj or typeof(obj) ~= \"Instance\" then return end\n        local lang = I18n.getCurrentLanguage()\n        if lang == \"en\" then return end\n        pcall(function()\n            if (obj:IsA(\"TextLabel\") or obj:IsA(\"TextButton\") or obj:IsA(\"TextBox\")) then\n                local currentText = obj.Text\n                if not currentText or #currentText == 0 then return end\n                \n                local dict = DICTIONARY[lang]\n                \n                local orig = obj:GetAttribute(\"NexusOrigText\")\n                if not orig or (dict and dict[currentText]) then\n                    orig = currentText\n                    obj:SetAttribute(\"NexusOrigText\", orig)\n                end\n                \n                if orig and #orig > 0 then\n                    if lang == \"en\" then\n                        if obj.Text ~= orig then\n                            obj.Text = orig\n                        end\n                    else\n                        local trans = dict and dict[orig]\n                        if trans and obj.Text ~= trans then\n                            obj.Text = trans\n                        end\n                    end\n                end\n            end\n        end)\n    end\n\n    local function applyLanguageToGui(gui)\n        if not gui then return end\n        pcall(function()\n            for _, desc in ipairs(gui:GetDescendants()) do\n                translateObject(desc)\n            end\n        end)\n    end\n\n    function I18n.applyLanguage()\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            applyLanguageToGui(pg:FindFirstChild(\"NexusPanel\"))\n            applyLanguageToGui(pg:FindFirstChild(\"NexusNotifications\"))\n        end\n        pcall(function()\n            local cg = game:GetService(\"CoreGui\")\n            if cg then\n                applyLanguageToGui(cg:FindFirstChild(\"NexusPanel\"))\n                applyLanguageToGui(cg:FindFirstChild(\"NexusNotifications\"))\n            end\n        end)\n    end\n\n    function I18n.initListeners()\n        local function hookGui(gui)\n            if not gui then return end\n            gui.DescendantAdded:Connect(function(desc)\n                task.wait(0.03)\n                translateObject(desc)\n            end)\n        end\n\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            local panel = pg:FindFirstChild(\"NexusPanel\")\n            if panel then hookGui(panel) end\n            local notifs = pg:FindFirstChild(\"NexusNotifications\")\n            if notifs then hookGui(notifs) end\n\n            pg.ChildAdded:Connect(function(child)\n                if child.Name == \"NexusPanel\" or child.Name == \"NexusNotifications\" then\n                    hookGui(child)\n                    task.wait(0.1)\n                    applyLanguageToGui(child)\n                end\n            end)\n        end\n\n        pcall(function()\n            local cg = game:GetService(\"CoreGui\")\n            if cg then\n                local panel = cg:FindFirstChild(\"NexusPanel\")\n                if panel then hookGui(panel) end\n                local notifs = cg:FindFirstChild(\"NexusNotifications\")\n                if notifs then hookGui(notifs) end\n\n                cg.ChildAdded:Connect(function(child)\n                    if child.Name == \"NexusPanel\" or child.Name == \"NexusNotifications\" then\n                        hookGui(child)\n                        task.wait(0.1)\n                        applyLanguageToGui(child)\n                    end\n                end)\n            end\n        end)\n    end\nend\n\n-- ===== FAKE NAME (STREAMER MODE) CORE =====\n-- ============================================================\ndo\n    local realName = LocalPlayer.Name\n    local realDisplayName = LocalPlayer.DisplayName\n    local fakeNameConn = nil\n    local fakeNameThread = nil\n    local maskIdsInText -- forward declare (dinh nghia ben duoi)\n\n    local function replacePlain(text, find, repl)\n        if find == \"\" then return text end\n        local parts = {}\n        local start = 1\n        while true do\n            local s, e = string.find(text, find, start, true)\n            if not s then\n                table.insert(parts, string.sub(text, start))\n                break\n            end\n            table.insert(parts, string.sub(text, start, s - 1))\n            table.insert(parts, repl)\n            start = e + 1\n        end\n        return table.concat(parts)\n    end\n\n    local function replaceTextInObject(obj)\n        if not NexusState.fakeNameEnabled then return end\n        if not obj or typeof(obj) ~= \"Instance\" then return end\n        pcall(function()\n            if typeof(obj) == \"Instance\" and typeof(obj) == \"Instance\" and obj:IsA(\"TextLabel\") or obj:IsA(\"TextButton\") or obj:IsA(\"TextBox\") then\n                local text = obj.Text\n                if text and #text > 0 then\n                    local updated = false\n                    if realDisplayName ~= \"\" and string.find(text, realDisplayName, 1, true) then\n                        text = replacePlain(text, realDisplayName, NexusState.fakeDisplayName or \"NexusPlayer\")\n                        updated = true\n                    end\n                    if realName ~= \"\" and string.find(text, realName, 1, true) then\n                        text = replacePlain(text, realName, NexusState.fakeName or \"NexusPlayer\")\n                        updated = true\n                    end\n                    -- Guild display: doi ten guild that -> fake guild de khong bi ban\n                    if NexusState.realGuildName and #NexusState.realGuildName > 0 then\n                        local rg = tostring(NexusState.realGuildName)\n                        if rg ~= \"ZION\" and not string.find(text, \"ZION\", 1, true) and string.find(text, rg, 1, true) then\n                            text = replacePlain(text, rg, NexusState.fakeGuildName or \"NexusGuild\")\n                            updated = true\n                        end\n                    end\n                    -- Che luon ID (UserId / PlaceId / JobId) chu khong chi ten\n                    if maskIdsInText then\n                        local masked, idChanged = maskIdsInText(text)\n                