              NexusLib:Notify({\n                                            Title = \"Quest\",\n                                            Message = \"Claimed \" .. selectedQuest,\n                                            Duration = 2\n                                        })\n                                    else\n                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1\n                                        if NexusState.ticketFailCount == 5 then\n                                            NexusLib:Notify({ Title = \"Quest\", Message = \"Claim failed 5 times. Check NPC or quest type.\", Duration = 4 })\n                                        end\n                                    end\n                                else\n                                    NexusState.ticketFailCount = 0\n                                end\n                            end)\n                            task.wait(0.5)\n                        end\n                    end)\n                else\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.ticketFailCount = 0\n                    NexusLib:Notify({ Title = \"Quest\", Message = \"Auto claim stopped\", Duration = 2 })\n                end\n            end\n        })\n    end\n\n    -- ===== AUTO DO TICKET QUEST =====\n    local DoSection = QuestsTab:CreateSection(\"Auto Do Ticket Quest\")\n    -- Store the dynamic controls\n    local islandModeDropdown = nil\n    local islandDropdown = nil\n    local islandDropdownFrame = nil\n    local selectedIslandMode = \"Auto Select Island\"\n    local selectedIslandName = \"Island 1\"\n    local islandList = {\"Island 1\", \"Island 2\", \"Island 3\", \"Island 4\", \"Island 5\",\n                        \"Island 6\", \"Island 7\", \"Island 8\", \"Island 9\", \"Island 10\", \"Island 11\", \"Island 12\", \"Island 13\"}\n\n    -- Remove the island dropdown (if present)\n    local function clearIslandDropdown()\n        if islandDropdownFrame and islandDropdownFrame._frame then\n            pcall(function()\n                if type(islandDropdownFrame.Destroy) == \"function\" then\n                    islandDropdownFrame:Destroy()\n                elseif islandDropdownFrame._frame and type(islandDropdownFrame._frame.Destroy) == \"function\" then\n                    islandDropdownFrame._frame:Destroy()\n                end\n            end)\n        end\n        islandDropdownFrame = nil\n        islandDropdown = nil\n    end\n\n    -- Create the island dropdown\n    -- NOTE: picking an island forces manual mode, so Auto Do Ticket\n    -- never pulls the player back to the recommended island.\n    local function createIslandDropdown()\n        clearIslandDropdown()\n        islandDropdown = Cfg.register(DoSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose an island\", {\n            Name = \"Choose an island\",\n            Options = islandList,\n            Default = selectedIslandName,\n            Callback = function(value)\n                selectedIslandName = value\n                selectedIslandMode = \"Choose Island Manual\"\n                pcall(function() if modeDropdown and modeDropdown.Set then modeDropdown:Set(\"Choose Island Manual\") end end)\n            end\n        })), \"Dropdown\", \"Choose an island\", {\n            Name = \"Choose an island\",\n            Options = islandList,\n            Default = selectedIslandName,\n            Callback = function(value)\n                selectedIslandName = value\n                selectedIslandMode = \"Choose Island Manual\"\n                pcall(function() if modeDropdown and modeDropdown.Set then modeDropdown:Set(\"Choose Island Manual\") end end)\n            end\n        })\n        islandDropdownFrame = islandDropdown\n    end\n\n    -- Create the mode dropdown\n    local modeDropdown = Cfg.register(DoSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Island Selection Mode\", {\n        Name = \"Island Selection Mode\",\n        Options = {\"Auto Select Island\", \"Choose Island Manual\"},\n        Default = \"Auto Select Island\",\n        Callback = function(value)\n            selectedIslandMode = value\n            if value == \"Choose Island Manual\" then\n                createIslandDropdown()\n            else\n                clearIslandDropdown()\n            end\n        end\n    })), \"Dropdown\", \"Island Selection Mode\", {\n        Name = \"Island Selection Mode\",\n        Options = {\"Auto Select Island\", \"Choose Island Manual\"},\n        Default = \"Auto Select Island\",\n        Callback = function(value)\n            selectedIslandMode = value\n            if value == \"Choose Island Manual\" then\n                createIslandDropdown()\n            else\n                clearIslandDropdown()\n            end\n        end\n    })\n\n    -- Create the default island dropdown (hidden, shown only in manual mode)\n    -- Not built up front, only once manual is picked\n\n    -- ===== Target island resolver =====\n    local function getTargetIsland()\n        if selectedIslandMode == \"Auto Select Island\" then\n            return getRecommendedIsland()\n        else\n            for _, island in ipairs(NexusState.islands) do\n                if island.name == selectedIslandName then\n                    return island\n                end\n            end\n            return nil\n        end\n    end\n\n\n    local function parseQuestString(str)\n        if not str or str == \"\" then return nil, nil end\n        local parts = {}\n        for part in string.gmatch(str, \"[^,]+\") do table.insert(parts, part) end\n        if #parts >= 3 then\n            local target = nil\n            local typ = nil\n            if string.find(parts[1], \"Boss\") then\n                target = tonumber(parts[3])\n                typ = parts[1]\n            else\n                target = tonumber(parts[2])\n                typ = parts[3]\n            end\n            if target and typ then return target, typ end\n        end\n        return nil, nil\n    end\n\n    local function getCurrentQuestProgress()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return nil end\n        local quest = userData:FindFirstChild(\"Quest\")\n        if not quest then return nil end\n        local main = quest:FindFirstChild(\"Main\")\n        if not main then return nil end\n        for _, folder in pairs(main:GetChildren()) do\n            if typeof(folder) == \"Instance\" and typeof(folder) == \"Instance\" and folder:IsA(\"Folder\") and (folder.Name == \"Easy Ticket Quest\" or folder.Name == \"Hard Ticket Quest\") then\n                local current = nil\n                local target = nil\n                local typ = nil\n                local questName = folder.Name\n                for _, child in pairs(folder:GetChildren()) do\n                    if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") or child:IsA(\"IntValue\") then\n                        if child.Name == \"1\" then\n                            current = child.Value\n                        end\n                    end\n                end\n                local objective = folder:FindFirstChild(\"Objective\")\n                if objective then\n                    for _, child in pairs(objective:GetChildren()) do\n                        if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"StringValue\") and child.Name == \"1\" then\n                            local val = child.Value\n                            if val and val ~= \"\" then\n                                NexusState.ticketObjectiveText = tostring(val)\n                                local t, ty = parseQuestString(val)\n                                if t and ty then\n                                    target = t\n                                    typ = ty\n                                end\n                            end\n                        end\n                    end\n                end\n                if current and target and typ then\n                    return current, target, questName, typ\n                end\n            end\n        end\n        return nil\n    end\n\n    local function updateQuestStatus()\n        local current, target, questName, typ = getCurrentQuestProgress(            end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"NPC not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA(\"BasePart\")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"Cannot find part to teleport to!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"Teleported to \" .. selectedNpc, Duration = 2 })\n            end\n        })\n        -- ===== LEARN SKILL NPC =====\n        local selectedLearnNpc = \"Sage Yijiu\"\n        \n        -- Dropdown with a single option\n        local learnDropdown = Cfg.register(NpcSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Learn Skill NPC\", {\n            Name = \"Learn Skill NPC\",\n            Options = {\"Sage Yijiu\"},\n            Default = \"Sage Yijiu\",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })), \"Dropdown\", \"Learn Skill NPC\", {\n            Name = \"Learn Skill NPC\",\n            Options = {\"Sage Yijiu\"},\n            Default = \"Sage Yijiu\",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected NPC\",\n            Callback = function()\n                local targetModel = workspace:FindFirstChild(\"NPC\") \n                    and workspace.NPC:FindFirstChild(\"LearnSkill\") \n                    and workspace.NPC.LearnSkill:FindFirstChild(\"Sage Yijiu\")\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"Learn Skill\", Message = \"Sage Yijiu not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA(\"BasePart\")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = \"Learn Skill\", Message = \"Cannot find part to teleport to!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = \"Learn Skill\", Message = \"Teleported to Sage Yijiu\", Duration = 2 })\n            end\n        })\n        -- ===== SECRET RODS SECTION =====\n        -- Secret Rod list (models parented to a Folder under workspace.SecretRod)\n        local function getSecretRodList()\n            local rods = {}\n            local secretRodFolder = workspace:FindFirstChild(\"SecretRod\")\n            if not secretRodFolder then return rods end\n            \n            for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                    table.insert(rods, child.Name)\n                end\n            end\n            return rods\n        end\n        \n        local rodList = getSecretRodList()\n        if #rodList == 0 then\n            table.insert(rodList, \"No Secret Rods found\")\n        end\n        \n        local selectedRod = rodList[1]\n        \n        -- Dropdown\n        local rodDropdown = NpcSection:CreateDropdown({\n            Name = \"Secret Rods\",\n            Options = rodList,\n            Default = selectedRod,\n            Callback = function(value)\n                selectedRod = value\n            end\n        })\n        \n        -- Teleport button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected Secret Rod\",\n            Callback = function()\n                if not selectedRod or selectedRod == \"No Secret Rods found\" then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"No Secret Rod selected!\", Duration = 2 })\n                    return\n                end\n                \n                local secretRodFolder = workspace:FindFirstChild(\"SecretRod\")\n                if not secretRodFolder then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"SecretRod folder not found!\", Duration = 2 })\n                    return\n                end\n                \n                local targetModel = nil\n                for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Name == selectedRod and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"Secret Rod not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA(\"BasePart\")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"Cannot find part to teleport to!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = \"Secret Rod\", Message = \"Teleported to \" .. selectedRod, Duration = 2 })\n            end\n        })\n    end\nend\n\n-- ============================================================\n-- ===== SETTINGS TAB =====\n-- ============================================================\ndo\n    local SettingsTab = Window:CreateTab(\"Settings\")\n\n    -- ===== CONFIG SECTION (save / load / auto-load / import-export) =====\n    do\n        local CfgUI = SettingsTab:CreateSection(\"Config\")\n        local Cfg = runtimeEnv.NexusConfig\n\n        CfgUI:CreateButton({\n            Name = \"Save Config\",\n            Callback = function() Cfg.save() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = \"Load Config\",\n            Callback = function() Cfg.load() end,\n        })\n\n        CfgUI:CreateToggle({\n            Name = \"Auto Load Config\",\n            Default = false,\n            Callback = function(value)\n                if not (writefile and isfile) then\n                    NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot save files.\", Duration = 3 })\n                    return\n                end\n                if value then\n                    Cfg.save(Cfg.AUTO_FILE)\n                else\n                    pcall(function()\n                        if isfile(Cfg.AUTO_FILE) and delfile then delfile(Cfg.AUTO_FILE) end\n                    end)\n                end\n            end,\n        })\n\n        CfgUI:CreateButton({\n            Name = \"Export Config (Copy Code)\",\n            Callback = function() Cfg.exportCode() end,\n        })\n\n        local importBox = CfgUI:CreateTextbox({\n            Name = \"Import Config Code\",\n            Placeholder = \"Paste code, then press Import\",\n            Default = \"\",\n            Callback = function() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = \"Import Config\",\n            Callback = function()\n                local code = \"\"\n                pcall(function() code = importBox.Get() end)\n                Cfg.importCode(code)\n            end,\n        })\n    end\n    local CharSection = SettingsTab:CreateSection(\"Character\")\n\n    Cfg.register(CharSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Walk Speed\", { Name = \"Walk Speed\", Placeholder = \"16\", Default = \"16\", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })), \"Textbox\", \"Walk Speed\", { Name = \"Walk Speed\", Placeholder = \"16\", Default = \"16\", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })\n\n    local function startFly()\n        local c = LocalPlayer.Character\n        if not c or not c:FindFirstChild(\"HumanoidRootPart\") then return end\n        if NexusState.flying then return end\n        if NexusState.bg then NexusState.bg:Destroy() end\n        if NexusState.bv then NexusState.bv:Destroy() end\n        local h = c.HumanoidRootPart\n        NexusState.bg = Instance.new(\"BodyGyro\", h)\n        NexusState.bg.P = 9e4\n        NexusState.bg.maxTorque = Vector3.new(9e9,9e9,9e9)\n        NexusState.bg.cframe = h.CFrame\n        NexusState.bv = Instance.new(\"BodyVelocity\", h)\n        NexusState.bv.velocity = Vector3.new(0,0,0)\n        NexusState.bv.maxForce = Vector3.new(9e9,9e9,9e9)\n        NexusState.flying = true\n        local humanoid = c:FindFirstChildOfClass(\"Humanoid\")\n        if humanoid then humanoid.PlatformStand = true end\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect() end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect() end\n        NexusState.flyInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)\n            if gameProcessed then return end\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = true end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = true end\n        end)\n        NexusState.flyInputEndConnection = UserInputService.InputEnded:Connect(function(input)\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = false end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = false end\n        end)\n    end\n\n    local function stopFly()\n        NexusState.flying = false\n        NexusState.flyKeys.Up, NexusState.flyKeys.Down = false, false\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect(); NexusState.flyInputConnection = nil end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect(); NexusState.flyInputEndConnection = nil end\n        if NexusState.bg then NexusState.bg:Destroy(); NexusState.bg = nil end\n        if NexusState.bv then NexusState.bv:Destroy(); NexusState.bv = nil end\n        local c = LocalPlayer.Character\n        if c then\n            local humanoid = c:FindFirstChildOfClass(\"Humanoid\")\n            if humanoid , cframe = CFrame.new(-297, 9, 12), power = 0},\n        {name = \"Island 2\", cframe = CFrame.new(-1274, 21, -270), power = 17},\n        {name = \"Island 3\", cframe = CFrame.new(57, 9, 1115), power = 28},\n        {name = \"Island 4\", cframe = CFrame.new(-1343, 9, 1083), power = 35},\n        {name = \"Island 5\", cframe = CFrame.new(-12, 9, -1696), power = 45},\n        {name = \"Island 6\", cframe = CFrame.new(-1184, 20, -1652), power = 55},\n        {name = \"Island 7\", cframe = CFrame.new(1470, 9, -1685), power = 62},\n        {name = \"Island 8\", cframe = CFrame.new(1130, 9, 1364), power = 72},\n        {name = \"Island 9\", cframe = CFrame.new(1459, 8, -248), power = 90},\n        {name = \"Island 10\", cframe = CFrame.new(3028, 16, -124), power = 100},\n        -- Island 11 (if u have ego and tiger): chi duoc recommend khi co ca rod Ego va Tiger\n        {name = \"Island 11\", cframe = CFrame.new(-2498.64966, 9.27561855, -215.078888, 0.444082469, 1.84874409e-08, -0.895985901, -3.89493522e-08, 1, 1.32894518e-09, 0.895985901, 3.43079094e-08, 0.444082469), power = 110},\n        {name = \"Island 12\", cframe = CFrame.new(-2912.0498, 6.76233578, 1200.33838, 0.272515684, -2.71757763e-08, 0.962151349, -1.71733454e-08, 1, 3.31089112e-08, -0.962151349, -2.55460559e-08, 0.272515684), power = 120},\n        {name = \"Island 13\", cframe = CFrame.new(-2690.31543, 6.76233625, -1313.08179, -0.539970279, 1.03704998e-07, 0.841684103, 7.36837009e-08, 1, -7.59405978e-08, -0.841684103, 2.10127347e-08, -0.539970279), power = 130},\n    },\n    Reroll = { method = \"Instant\", teleported = false, oldPosition = nil, running = false, thread = nil },\n    buyRod = { method = \"Instant\", teleported = false, oldPosition = nil },\n    learnSkill = { method = \"Instant\", teleported = false, oldPosition = nil },\n    upgradeSkill = { method = \"Instant\", teleported = false, oldPosition = nil },\n    exchange = { method = \"Instant\", teleported = false, oldPosition = nil },\n    upgradeCharacter = { method = \"Instant\", teleported = false, oldPosition = nil },\n    favorites = { selectedFish = {}, autoEnabled = false, thread = nil },\n    AutoFarm = {\n        enabled = false,\n        selectedIsland = nil,\n        filter1 = nil,\n        filter2 = nil,\n        targetFishName = \"\",\n        teleported = false,\n        thread = nil,\n    },\n    LastMaoshan = false,\n    LastTaoist = false,\n    LastSpirit = false,\n    LastWeather = nil,\n    reportedJobId = game.JobId,\n    autoRecommendRunning = false,\n    autoRecommendThread = nil,\n    autoRebirthRunning = false,\n    autoRebirthThread = nil,\n    autoCraftRunning = false,\n    autoCraftThread = nil,\n    autoGachaRunning = false,\n    autoGachaThread = nil,\n    autoDoRunning = false,\n    autoDoThread = nil,\n    autoClaimRunning = false,\n    autoClaimThread = nil,\n    ticketTargetCount = 0,\n    ticketCurrentCount = 0,\n    ticketQuestActive = false,\n    ticketQuestClaimed = false,\n    savedRoutineFlags = nil,\n    craftBaitQuantity = 1,\n    craftBaitName = \"Rainbow Bait\",\n    selectedBait = nil,\n    buyBaitQuantity = 10,\n    buyBaitThreshold = 5,\n    selectedOptions = {\"Cash\", \"Level\"},\n    UpgradeCharacter = nil,\n    flying = false,\n    flySpeed = 50,\n    bg = nil,\n    bv = nil,\n    flyInputConnection = nil,\n    flyInputEndConnection = nil,\n    flyKeys = { Up = false, Down = false },\n    waterY = nil,\n    waterPart = nil,\n    waterPartsList = {},\n    waterWalkConnection = nil,\n    waterWalkEnabled = false,\n    BossKeywords = { \"boss\", \"raid\", \"giant\", \"king\", \"lord\" },\n    SecretBossKeywords = { \"secret\", \"hidden\", \"mythic\", \"event\", \"rare\" },\n    BossNameSet = {},\n    SecretBossNameSet = {},\n    autoCraftRodRunning = false,\n    autoCraftRodThread = nil,\n    enzoHitIndex = 0,\n    enzoPhaseActive = false,\n    enzoNextClick = 0,\n    fullBrightApplied = false,\n    enzoPrevP = nil,\n    enzoDir = 0,\n    enzoArmed = true,\n    autoGachaToggleRef = nil,\n    sellMethod1 = \"Spam\",\n    sellMethod2 = \"Instant\",\n    lastPosition = nil,\n    sellCooldown = 0,\n    craftRodMethod = \"Instant\",\n    lastCraftPosition = nil,\n    craftBaitMethod = \"Instant\",\n    buyBaitMethod = \"Instant\",\n    lastCraftBaitPosition = nil,\n    lastBuyBaitPosition = nil,\n    spectateToggle = false,\n    notificationsEnabled = true,\n    fakeNameEnabled = false,\n    fakeName = \"NexusPlayer\",\n    fakeDisplayName = \"NexusPlayer\",\n    fakeUserId = \"0\",\n    fakeIdMode = 1,\n    -- Guild display (neu game hien ten guild canh ten player -> doi ten guild\n    -- de khong bi report/ban). realGuildName=\"\" thi bo qua.\n    realGuildName = \"\",\n    fakeGuildName = \"NexusGuild\",\n    antiReportEnabled = true,\n    currentLanguage = \"auto\",\n    skillSeqIndex = 1,\n    lastSkillCastTime = 0,\n    SmartWeather = {\n        enabled = false,\n        selectedIslands = {\n            [\"Island 2\"] = true,\n            [\"Island 3\"] = true,\n            [\"Island 5\"] = true,\n            [\"Island 6\"] = true,\n            [\"Island 7\"] = true,\n            [\"Island 8\"] = true,\n        },\n        activeOverride = false,\n        savedCFrame = nil,\n        savedFlags = nil,\n        targetIsland = nil,\n    },\n    questFarmingIsland = \"Auto (Recommend)\",\n    isDoingUseBaitQuest = false,\n}\ndo\n    -- Override NexusLib.Notify de kiem tra toggle va ho tro ca method (:) lan direct (.)\n    if NexusLib and NexusLib.Notify then\n        local originalNotify = NexusLib.Notify\n        NexusLib.Notify = function(selfOrConfig, maybeConfig)\n            if NexusState and NexusState.notificationsEnabled == false then\n                return\n            end\n            local config = maybeConfig\n            if not config and type(selfOrConfig) == \"table\" then\n                if selfOrConfig.Title or selfOrConfig.Message or selfOrConfig.Duration then\n                    config = selfOrConfig\n                end\n            end\n            config = config or {}\n\n            pcall(function()\n                originalNotify(NexusLib, config)\n            end)\n        end\n    end\nend\n\n-- ============================================================\n-- ===== NEXUS USERS PROTECTION (ANTI-REPORT) =====\n-- ============================================================\ndo\n    pcall(function()\n        LocalPlayer:SetAttribute(\"NexusUser\", true)\n        if LocalPlayer.Character then\n            LocalPlayer.Character:SetAttribute(\"NexusUser\", true)\n        end\n        LocalPlayer.CharacterAdded:Connect(function(char)\n            pcall(function()\n                LocalPlayer:SetAttribute(\"NexusUser\", true)\n                char:SetAttribute(\"NexusUser\", true)\n            end)\n        end)\n    end)\n\n    pcall(function()\n        if hookmetamethod and not _G.NexusNamecallHooked then\n            _G.NexusNamecallHooked = true\n            local oldNamecall\n            oldNamecall = hookmetamethod(game, \"__namecall\", function(self, ...)\n                local method = getnamecallmethod()\n                if (method == \"ReportAbuse\" or method == \"reportAbuse\") and self == Players then\n                    local args = {...}\n                    local target = args[1]\n                    local isNexusUser = false\n                    if typeof and typeof(target) == \"Instance\" then\n                        if typeof(target) == \"Instance\" and typeof(target) == \"Instance\" and target:IsA(\"Player\") then\n                            if target:GetAttribute(\"NexusUser\") or (target.Character and target.Character:GetAttribute(\"NexusUser\")) then\n                                isNexusUser = true\n                            end\n                        end\n                    elseif type(target) == \"string\" then\n                        local p = Players:FindFirstChild(target)\n                        if p and (p:GetAttribute(\"NexusUser\") or (p.Character and p.Character:GetAttribute(\"NexusUser\"))) then\n                            isNexusUser = true\n                        end\n                    end\n                    if isNexusUser and NexusState.antiReportEnabled ~= false then\n                        NexusLib:Notify({\n                            Title = \"Nexus Shield\",\n                            Message = \"You cannot report another Nexus Hub user!\",\n                            Duration = 3\n                        })\n                        return nil\n                    end\n                end\n                return oldNamecall(self, ...)\n            end)\n        end\n    end)\nend\n\n-- ============================================================\n-- ===== AUTO LANGUAGE (I18N) =====\n-- ============================================================\nlocal I18n = {}\ndo\n    local LocalizationService = Services.LocalizationService or game:GetService(\"LocalizationService\")\n    local rawLocale = \"en\"\n    pcall(function()\n        rawLocale = string.lower(\n            LocalizationService.RobloxLocaleId \n            or LocalizationService.SystemLocaleId \n            or (LocalizationService.GetRobloxLocaleId and LocalizationService:GetRobloxLocaleId()) \n            or (LocalizationService.GetSystemLocaleId and LocalizationService:GetSystemLocaleId()) \n            or \"en\"\n        )\n    end)\n\n    local autoLang = \"en\"\n    if string.find(rawLocale, \"^th\") then\n        autoLang = \"th\"\n    elseif string.find(rawLocale, \"^id\") then\n        autoLang = \"id\"\n    elseif string.find(rawLocale, \"^es\") then\n        autoLang = \"es\"\n    elseif string.find(rawLocale, \"^pt\") then\n        autoLang = \"pt\"\n    elseif string.find(rawLocale, \"^zh\") then\n        autoLang = \"zh\"\n    elseif string.find(rawLocale, \"^ru\") then\n        autoLang = \"ru\"\n    end\n\n    NexusState.detectedLanguage = autoLang\n\n    local DICTIONARY = {\n        es = {\n            [\"Session\"] = \"Sesi\u{F3}n\",\n            [\"Routine\"] = \"Pesca\",\n            [\"Shop\"] = \"Tienda\",\n            [\"Exchange\"] = \"Intercambio\",\n            [\"Quests\"] = \"Misiones\",\n            [\"Upgrade\"] = \"Mejoras\",\n            [\"Teleport\"] = \"Teletransporte\",\n            [\"Settings\"] = \"Ajustes\",\n            [\"Session overview\"] = \"Resumen de la sesi\u{F3}n\",\n            [\"Release notes\"] = \"Notas de la versi\u{F3}n\",\n            [\"Fishing routine\"] = \"Rutina de pesca\",\n            [\"Farm On Weather Section\"] = \"Auto Farm por Clima\",\n            [\"Skill profile\"] = \"Perfil de habilidades\",\n            [\"Auto Equip\"] = \"Auto Equipar\",\n            [\"Auto Nameless Octoparasite\"] = \"Auto Pulpo Sin Nombre\",\n            [\"Auto Favorite Fish\"] = \"Auto Favorito de Peces\",\n            [\"Auto Pray Spirit\"] = \"Auto Rezar al Esp\u{ED}ritu\",\n            [\"Auto Farm\"] = \"Auto Farm\",\n            [\"Index\"] = \"\u{CD}ndice de Peces\",\n            [\"Upgrade Skill\"] = \"Mejorar Habilidad\",\n            [\"Craft Rod\"] = \"Fabricar Ca\u{F1}a\",\n            [\"Auto Buy Bait\"] = \"Auto Comprar Cebo\