rn\n    task.spawn(function()\n        pcall(function()\n            local StarterGui = game:GetService(\"StarterGui\")\n            StarterGui:SetCore(\"SendNotification\", {\n                Title = \"Nexus Security\",\n                Text = \"Tamper detected: \" .. tostring(reason),\n                Duration = 10\n            })\n        end)\n        task.wait(2)\n        pcall(function()\n            local lp = game:GetService(\"Players\").LocalPlayer\n            if lp then lp:Kick(\"Nexus Security: Tamper detected (\" .. tostring(reason) .. \")\") end\n        end)\n        while true do end\n    end)\nend\n\nlocal function verifyHttpIntegrity()\n    return true\nend\nverifyHttpIntegrity()\n\n\n\n-- ============================================================\n-- ===== BOOT DIAGNOSTIC / CHONG CHET IM LANG =====\n-- Nhieu executor (nhat la UNC/sUNC cao tren mobile) KHONG hien console,\n-- nen khi script chet giua duong thi nguoi dung chi thay \"khong len gi\".\n-- Block nay dam bao MOI that bai deu hien ra man hinh: ve banner bang\n-- Instance.new thuan -> khong can NexusLib, khong can CoreGui, khong can console.\n-- ============================================================\ndo\n    local _rt = (getgenv and getgenv()) or _G\n\n    -- Don banner cua lan execute truoc\n    pcall(function()\n        if _rt.NexusBootGui then _rt.NexusBootGui:Destroy() end\n    end)\n    _rt.NexusBootGui = nil\n\n    local boot = { stage = \"bat dau\", done = false }\n    _rt.NexusBoot = boot\n\n    local execName = \"?\"\n    pcall(function()\n        if identifyexecutor then execName = tostring((identifyexecutor())) end\n    end)\n\n    -- Tim cho parent ScreenGui: uu tien gethui (duoc bao ve), roi PlayerGui,\n    -- cuoi cung CoreGui. Tat ca boc pcall vi 1 so executor chan CoreGui.\n    local function guiHome()\n        local tries = {\n            function() return gethui and gethui() end,\n            function() return game:GetService(\"Players\").LocalPlayer:FindFirstChild(\"PlayerGui\") end,\n            function() return game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerGui\", 10) end,\n            function() return game:GetService(\"CoreGui\") end,\n        }\n        for _, f in ipairs(tries) do\n            local ok, v = pcall(f)\n            if ok and typeof(v) == \"Instance\" then return v end\n        end\n        return nil\n    end\n\n    local function banner(title, body)\n        local home = guiHome()\n        if not home then return false end\n        local ok = pcall(function()\n            pcall(function()\n                if _rt.NexusBootGui then _rt.NexusBootGui:Destroy() end\n            end)\n            local sg = Instance.new(\"ScreenGui\")\n            sg.Name = \"NexusBootReport\"\n            sg.ResetOnSpawn = false\n            sg.IgnoreGuiInset = true\n            sg.DisplayOrder = 2147483647\n            sg.Parent = home\n            _rt.NexusBootGui = sg\n\n            local frame = Instance.new(\"Frame\")\n            frame.Size = UDim2.new(0, 400, 0, 175)\n            frame.Position = UDim2.new(0.5, -200, 0, 30)\n            frame.BackgroundColor3 = Color3.fromRGB(30, 21, 26)\n            frame.BorderSizePixel = 0\n            frame.Parent = sg\n\n            local corner = Instance.new(\"UICorner\")\n            corner.CornerRadius = UDim.new(0, 10)\n            corner.Parent = frame\n\n            local stroke = Instance.new(\"UIStroke\")\n            stroke.Color = Color3.fromRGB(232, 88, 100)\n            stroke.Thickness = 2\n            stroke.Parent = frame\n\n            local head = Instance.new(\"TextLabel\")\n            head.Size = UDim2.new(1, -20, 0, 26)\n            head.Position = UDim2.new(0, 12, 0, 9)\n            head.BackgroundTransparency = 1\n            head.Font = Enum.Font.GothamBold\n            head.TextSize = 16\n            head.TextColor3 = Color3.fromRGB(255, 122, 132)\n            head.TextXAlignment = Enum.TextXAlignment.Left\n            head.Text = tostring(title)\n            head.Parent = frame\n\n            local body2 = Instance.new(\"TextLabel\")\n            body2.Size = UDim2.new(1, -24, 1, -74)\n            body2.Position = UDim2.new(0, 12, 0, 38)\n            body2.BackgroundTransparency = 1\n            body2.Font = Enum.Font.Gotham\n            body2.TextSize = 13\n            body2.TextColor3 = Color3.fromRGB(236, 236, 242)\n            body2.TextWrapped = true\n            body2.TextXAlignment = Enum.TextXAlignment.Left\n            body2.TextYAlignment = Enum.TextYAlignment.Top\n            body2.Text = tostring(body)\n            body2.Parent = frame\n\n            local foot = Instance.new(\"TextLabel\")\n            foot.Size = UDim2.new(1, -100, 0, 16)\n            foot.Position = UDim2.new(0, 12, 1, -26)\n            foot.BackgroundTransparency = 1\n            foot.Font = Enum.Font.Gotham\n            foot.TextSize = 11\n            foot.TextColor3 = Color3.fromRGB(150, 150, 162)\n            foot.TextXAlignment = Enum.TextXAlignment.Left\n            foot.Text = \"executor: \" .. execName\n            foot.Parent = frame\n\n            local close = Instance.new(\"TextButton\")\n            close.Size = UDim2.new(0, 72, 0, 24)\n            close.Position = UDim2.new(1, -84, 1, -32)\n            close.BackgroundColor3 = Color3.fromRGB(62, 46, 53)\n            close.Font = Enum.Font.GothamBold\n            close.TextSize = 12\n            close.TextColor3 = Color3.fromRGB(255, 255, 255)\n            close.Text = \"Dong\"\n            close.AutoButtonColor = true\n            close.Parent = frame\n\n            local cc = Instance.new(\"UICorner\")\n            cc.CornerRadius = UDim.new(0, 6)\n            cc.Parent = close\n\n            close.MouseButton1Click:Connect(function()\n                pcall(function() sg:Destroy() end)\n            end)\n        end)\n        return ok\n    end\n\n    -- Bao loi ra MOI kenh co the co\n    _rt.NexusReport = function(title, body)\n        local line = \"[Nexus] \" .. tostring(title) .. \" | \" .. tostring(body)\n        pcall(function() print(line) end)\n        pcall(function() warn(line) end)\n        pcall(function() if rconsoleprint then rconsoleprint(line .. \"\\n\") end end)\n        pcall(function()\n            local slib = _rt.NexusLib\n            if slib and slib.Notify then\n                slib:Notify({ Title = tostring(title), Message = tostring(body), Duration = 14 })\n            end\n        end)\n        pcall(function() banner(title, body) end)\n    end\n\n    -- Danh dau dang o buoc nao (watchdog se in ra buoc nay neu treo)\n    _rt.NexusStage = function(name)\n        if _rt.NexusBoot == boot then boot.stage = tostring(name) end\n    end\n\n    -- Cho co cua so / con children -> bao ro thay vi treo im lang\n    _rt.NexusNeedChild = function(parent, childName, timeout)\n        timeout = timeout or 30\n        if typeof(parent) ~= \"Instance\" then\n            _rt.NexusReport(\"Nexus: failed to start\",\n                \"No parent to search for '\" .. tostring(childName) .. \"'.\")\n            return nil\n        end\n        local ok, inst = pcall(function()\n            return parent:WaitForChild(childName, timeout)\n        end)\n        if ok and inst then return inst end\n        _rt.NexusReport(\"Nexus: game data missing\",\n            \"Could not find '\" .. tostring(childName) .. \"' sau \" .. tostring(timeout) .. \"s.\\n\" ..\n            \"1) Wrong game? This script is only for [UPD] Heavyweight Fishing.\\n\" ..\n            \"2) If you just joined, wait for the game to load, then execute again.\")\n        return nil\n    end\n\n    -- WATCHDOG: 50s ma UI chua len -> bao dang tac o buoc nao.\n    -- Day la cai bat MOI loi chet im lang, ke ca loi tuong lai chua biet.\n    task.spawn(function()\n        for _ = 1, 50 do\n            task.wait(1)\n            if _rt.NexusBoot ~= boot then return end\n            if boot.done then return end\n        end\n        if _rt.NexusBoot ~= boot or boot.done then return end\n        _rt.NexusReport(\"Nexus: the script failed to start\",\n            \"Stopped at stage: \" .. tostring(boot.stage) .. \"\\n\" ..\n            \"Screenshot this panel and send it to the admin.\")\n    end)\nend\n-- ===== END BOOT DIAGNOSTIC =====\n\n-- ============================================================\n-- ===== ANTI-BYPASS GUARD (freemium) v2 =====\n-- Chan chay chua: phai co key hop le HOAC da duoc Key System xac thuc.\n-- An toan: khong kick khi loi mang / executor khong ho tro http.\n-- ============================================================\ndo\n    local _rt = (getgenv and getgenv()) or _G\n    pcall(function() _rt.NexusStage(\"key check\") end)\n\n    local Players = game:GetService(\"Players\")\n    local HttpService = game:GetService(\"HttpService\")\n    local LP = Players.LocalPlayer\n\n    -- Anti-Hook / Anti-Dump check\n    local _raw_loadstring = loadstring\n    local function isHooked(f)\n        if type(f) ~= \"function\" then return false end\n        if ishooked and ishooked(f) then return true end\n        return false\n    end\n    if isHooked(_raw_loadstring) or (loadstring and isHooked(loadstring)) then\n        LP:Kick(\"Nexus Security: loadstring tampering detected.\")\n        while true do task.wait(9999) end\n        return\n    end\n\n    local GUARD = {\n        API_URL = \"https://vgvaxescpirfdkrcamyk.supabase.co/functions/v1/key-system\",\n        PROTOCOL_VERSION = 3,\n        -- Freemium chi doc file FREEMIUM (khong doc file premium de tranh de lan)\n        KEY_FILES = { \"NexusFreemiumKey.txt\" },\n        TIMEOUT = 20,\n        RETRY = 2,\n        -- Doi thanh true neu muon: khong tim thay key thi VAN CHAY (che do offline).\n        OFFLINE_FALLBACK = true,\n    }\n\n    local function getHWID()\n        local candidates = {\n            function() return gethwid and gethwid() end,\n            function() return game:GetService(\"RbxAnalyticsService\"):GetClientId() end,\n        }\n        for _, getter in ipairs(candidates) do\n            local ok, value = pcall(getter)\n            if ok and type(value) == \"string\" and #value >= 8 then\n                return value .. \":\" .. tostring(LP.UserId)\n            end\n        end\n        return string.format(\"player:%d:place:%d\", LP.UserId, game.PlaceId)\n    end\n\n    local _raw_req = (syn and syn.request) or http_request or request or (fluxus and fluxus.request)\n    local function requestAdapter()\n        return _raw_req or (syn and syn.request) or http_request or request or (fluxus and fluxus.request)\n    end\n\n    local function api(action, fields)\n        local payload = fields or {}\n        payload.action = action\n        payload.protocol_version = GUARD.PROTOCOL_VERSION\n        payload.hwid = getHWID()\n        local lastErr = \"NETWORK_ERROR\"\n        for _ = 1, GUARD.RETRY do\n            local ok, result = pcall(function()\n                local requestFn = requestAdapter()\n                local encoded = HttpService:JSONEncode(payload)\n                if requestFn then\n                    local raw = requestFn({\n                        Url = GUARD.API_URL, Method = \"POST\",\n                        Headers = { [\"Content-Type\"] = \"application/json\" },\n                        Body = encode",
